        SQLAlchemySignalChainRepository,
    )

    repo = SQLAlchemySignalChainRepository(db)
    chains = await repo.get_by_user_id(current_user.id)

    chain_items = []
    for chain in chains:
        if search and search.lower() not in chain.name.lower():
            continue
        chain_items.append(
            {
                "id": str(chain.id),
                "name": chain.name,
                "block_count": chain.block_count,
